-    expect(res).toEqual({ id: 'pre_1', encontroId: 'enc_1', participanteId: 'p-carla', origem: 'manual', lidoEm: '...', registradaEm: '...', justificativa: 'Justificativa válida' });
+    expect(res).toEqual({
