import { useState } from 'react';
import { api } from '../api/client';
import { ApiError } from '../api/types';

export function useRegistrarPresencaManual(encontroId?: string, apiClient = api) {
  const [participanteId, setParticipanteId] = useState('');
  const [justificativa, setJustificativa] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);
  const [error, setError] = useState<{ erro: string; mensagem: string } | null>(null);

  const registrarManual = async () => {
    if (!encontroId) {
      setError({ erro: 'ENCONTRO_NAO_INFORMADO', mensagem: 'ID do encontro não informado.' });
      return;
    }

    setSubmitting(true);
    setError(null);
    setSuccessMessage(null);

    try {
      const result = await apiClient.registrarPresencaManual(encontroId, {
        participanteId: participanteId.trim(),
        justificativa: justificativa.trim(),
      });
      setSubmitting(false);
      setParticipanteId('');
      setJustificativa('');

      const status = (result as any).status !== undefined ? (result as any).status : 201;
      if (status === 201) {
        setSuccessMessage('Presença manual registrada agora.');
      } else if (status === 200) {
        setSuccessMessage('Presença já existia.');
      } else {
        setSuccessMessage('Presença manual registrada com sucesso.');
      }
    } catch (err: any) {
      setSubmitting(false);

      if (err instanceof ApiError) {
        let mensagem = err.mensagem;
        if (err.erro === 'JUSTIFICATIVA_OBRIGATORIA') {
          mensagem = 'A justificativa é obrigatória (mínimo 10 caracteres).';
        } else if (err.erro === 'NAO_INSCRITO') {
          mensagem = 'Participante não elegível.';
        } else if (err.erro === 'FORA_DA_JANELA') {
          mensagem = 'Fora do horário permitido para lançamento manual.';
        } else if (err.erro === 'LIMITE_DE_MANUAIS') {
          mensagem = 'Limite de presenças manuais atingido para este encontro.';
        }
        setError({ erro: err.erro, mensagem });
      } else {
        setError({
          erro: 'ERRO_DE_REDE',
          mensagem: err.message || 'Erro de rede genérico.',
        });
      }
    }
  };

  return {
    participanteId,
    setParticipanteId,
    justificativa,
    setJustificativa,
    submitting,
    successMessage,
    error,
    registrarManual,
  };
}

import React from 'react';
import { useRegistrarPresencaManual } from '../hooks/useRegistrarPresencaManual';
import { api } from '../api/client';

interface RegistrarPresencaManualProps {
  encontroId?: string;
  id?: string;
  apiClient?: typeof api;
}

export function RegistrarPresencaManual({
  encontroId,
  id,
  apiClient = api,
}: RegistrarPresencaManualProps) {
  const targetId = encontroId || id;
  const {
    participanteId,
    setParticipanteId,
    justificativa,
    setJustificativa,
    submitting,
    successMessage,
    error,
    registrarManual,
  } = useRegistrarPresencaManual(targetId, apiClient);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    registrarManual();
  };

  return (
    <section className="registrar-presenca-manual-container" data-testid="registrar-presenca-manual-container">
      <div className="page-heading">
        <div>
          <span className="eyebrow">Organização</span>
          <h2>Lançar Presença Manual</h2>
          <p>Registre a presença de um participante manualmente informando o ID e a justificativa.</p>
        </div>
      </div>

      {successMessage && (
        <div className="success-message" role="status" aria-live="polite" data-testid="success-message">
          {successMessage}
        </div>
      )}

      {error && (
        <div className="error-message" role="alert" data-testid="error-message">
          <strong>Erro ({error.erro}):</strong> <span>{error.mensagem}</span>
        </div>
      )}

      <form onSubmit={handleSubmit} className="form-card">
        <div className="field">
          <label htmlFor="participante-id-input">ID do Participante:</label>
          <input
            id="participante-id-input"
            type="text"
            value={participanteId}
            onChange={(e) => setParticipanteId(e.target.value)}
            placeholder="Ex.: p-carla"
            required
            disabled={submitting}
            data-testid="participante-id-input"
          />
        </div>

        <div className="field">
          <label htmlFor="justificativa-input">Justificativa:</label>
          <textarea
            id="justificativa-input"
            value={justificativa}
            onChange={(e) => setJustificativa(e.target.value)}
            placeholder="Informe a justificativa (mínimo de 10 caracteres)..."
            required
            rows={4}
            disabled={submitting}
            data-testid="justificativa-input"
          />
        </div>

        <div className="form-actions">
          <button
            type="submit"
            disabled={submitting || !participanteId.trim() || !justificativa.trim()}
            className="button button--primary"
            data-testid="submit-button"
          >
            {submitting ? 'Registrando...' : 'Registrar Presença Manual'}
          </button>
        </div>
      </form>
    </section>
  );
}

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { RegistrarPresencaManual } from './RegistrarPresencaManual';
import { api } from '../api/client';
import { ApiError } from '../api/types';

describe('RegistrarPresencaManual Component', () => {
  beforeEach(() => {
    localStorage.clear();
    vi.restoreAllMocks();
  });

  it('deve registrar presença manual com sucesso 201 e limpar os campos', async () => {
    const registrarPresencaManualMock = vi.fn().mockResolvedValue({
      presenca: {
        id: 'pre_1',
        encontroId: 'enc_1',
        participanteId: 'p-carla',
        origem: 'manual',
        lidoEm: null,
        registradaEm: '2026-10-19T10:00:01-03:00',
        justificativa: 'Participante chegou atrasado por motivo de força maior.',
      },
      status: 201,
    });

    const fakeClient = {
      ...api,
      registrarPresencaManual: registrarPresencaManualMock,
    };

    render(<RegistrarPresencaManual encontroId="enc_1" apiClient={fakeClient} />);

    const participanteInput = screen.getByTestId('participante-id-input');
    const justificativaInput = screen.getByTestId('justificativa-input');
    const submitBtn = screen.getByTestId('submit-button');

    await userEvent.type(participanteInput, 'p-carla');
    await userEvent.type(justificativaInput, 'Participante chegou atrasado por motivo de força maior.');

    expect(participanteInput).toHaveValue('p-carla');
    expect(justificativaInput).toHaveValue('Participante chegou atrasado por motivo de força maior.');

    fireEvent.click(submitBtn);

    await waitFor(() => {
      expect(screen.getByTestId('success-message')).toHaveTextContent('Presença manual registrada agora.');
    });

    expect(registrarPresencaManualMock).toHaveBeenCalledWith('enc_1', {
      participanteId: 'p-carla',
      justificativa: 'Participante chegou atrasado por motivo de força maior.',
    });
    expect(participanteInput).toHaveValue('');
    expect(justificativaInput).toHaveValue('');
  });

  it('deve lidar com sucesso 200 (idempotência - presença já existia) e limpar os campos', async () => {
    const registrarPresencaManualMock = vi.fn().mockResolvedValue({
      presenca: {
        id: 'pre_1',
        encontroId: 'enc_1',
        participanteId: 'p-carla',
        origem: 'manual',
        lidoEm: null,
        registradaEm: '2026-10-19T10:00:01-03:00',
        justificativa: 'Justificativa válida',
      },
      status: 200,
    });

    const fakeClient = {
      ...api,
      registrarPresencaManual: registrarPresencaManualMock,
    };

    render(<RegistrarPresencaManual encontroId="enc_1" apiClient={fakeClient} />);

    const participanteInput = screen.getByTestId('participante-id-input');
    const justificativaInput = screen.getByTestId('justificativa-input');

    await userEvent.type(participanteInput, 'p-carla');
    await userEvent.type(justificativaInput, 'Justificativa válida');

    fireEvent.click(screen.getByTestId('submit-button'));

    await waitFor(() => {
      expect(screen.getByTestId('success-message')).toHaveTextContent('Presença já existia.');
    });

    expect(participanteInput).toHaveValue('');
